    "                for i=1,1000 do\n"
    "                    if not data.item_detail[i] then\n"
    "                        data.item_detail[i] = { count = 1, expire_ts = 0 }\n"
    "                    end ------ AKMOD\n"
    "                end\n"
    "            end\n"
    "            return old(_, uid, data)\n"
    "        end\n"
    "    end\n"
    "    return true\n"
    "end\n"
