    "if not GameStatus then error(\"status not ready\") end\n"
    "if not ModuleManager then error(\"module manager not ready\") end\n";

typedef int (*luaL_loadbuffer_t)(void *L, const char *buff, size_t sz, const char *name, const char *mode);
typedef int (*lua_pcall_t)(void *L, int nargs, int nresults, int errfunc, void *ctx, void *k);

static uintptr_t LuaModuleBase() {
    uint32_t count = _dyld_image_count();
    for (uint32_t i = 0; i < count; i++) {
        const char *name = _dyld_get_image_name(i);
        if (!name) continue;
        if (strstr(name, "ShadowTrackerExtra.app/ShadowTrackerExtra")) {
            return (uintptr_t)_dyld_get_image_vmaddr_slide(i);
        }
    }
    return 0;
}

static bool LuaValidAddr(uintptr_t a) {
    return a > 0x100000000ULL && a < 0x2000000000ULL;
}

static bool LuaRead(uintptr_t addr, void *buffer, size_t len) {
    if (!LuaValidAddr(addr)) return false;
    vm_size_t size = 0;
    kern_return_t err = vm_read_overwrite(mach_task_self(), (vm_address_t)addr,
                                          (vm_size_t)len, (vm_address_t)buffer, &size);
    return err == KERN_SUCCESS && size == (vm_size_t)len;
}

template <typename T>
static T LuaReadT(uintptr_t addr) {
    T data{};
    LuaRead(addr, &data, sizeof(T));
    return data;
}

static uintptr_t LuaHex(const char *s) {
    if (!s) return 0;
    return (uintptr_t)strtoull(s, nullptr, 16);
}

static bool LuaInText(uintptr_t address) {
    static uintptr_t textStart = 0, textEnd = 0;
    if (!textStart) {
        uintptr_t base = LuaModuleBase();
        if (!base) return false;
        const struct mach_header_64 *hdr = (const struct mach_header_64 *)(base + 0x100000000ULL);
        if (hdr->magic != MH_MAGIC_64) return false;
        const uint8_t *p = (const uint8_t *)(hdr + 1);
        for (uint32_t i = 0; i < hdr->ncmds; i++) {
            const struct load_command *lc = (const struct load_command *)p;
            if (lc->cmd == LC_SEGMENT_64) {
                const struct segment_command_64 *seg = (const struct segment_command_64 *)lc;
                if (strcmp(seg->segname, "__TEXT") == 0) {
                    textStart = base + seg->vmaddr;
                    textEnd = textStart + seg->vmsize;
                    break;
                }
            }
            p += lc->cmdsize;
        }
        if (!textStart) return false;
    }
    return address >= textStart && address < textEnd;
}

static int LuaAppIndex() {
    NSString *bid = [[NSBundle mainBundle] infoDictionary][@"CFBundleIdentifier"];
    if (bid) {
        const char *c = [bid UTF8String];
        if (c) {
            if (strstr(c, ENCRYPT("imobile"))) return APP_IMB;
            if (strstr(c, ENCRYPT("rekoo")))   return APP_REKOO;
            if (strstr(c, ENCRYPT("kr")))      return APP_KR;
            if (strstr(c, ENCRYPT("vn")))      return APP_VN;
            if (strstr(c, ENCRYPT("ig")))      return APP_IG;
        }
    }
    return APP_IG;
}

static void *LuaResolve(const char *symbol, const char *configured, uintptr_t base) {
    uintptr_t v = LuaHex(configured);
    if (v) {
        uintptr_t addr = base + v;
        if (LuaInText(addr)) return (void *)addr;
    }
    return dlsym(RTLD_DEFAULT, symbol);
}

static void LuaPushUnique(std::vector<uintptr_t> &v, uintptr_t x) {
    if (!LuaValidAddr(x)) return;
    for (uintptr_t e : v) if (e == x) return;
    v.push_back(x);
}

static void LuaCollectStates(uintptr_t wrapper, std::vector<uintptr_t> &out) {
    if (!LuaValidAddr(wrapper)) return;
    LuaPushUnique(out, LuaReadT<uintptr_t>(wrapper + CFG_WRAPPER_TO_STATE));
}

static bool LuaRunChunk(void *L, luaL_loadbuffer_t loadbuf, lua_pcall_t pcall,
                        const char *code) {
    if (loadbuf(L, code, strlen(code), "dex", 0) != 0) return false;
    return pcall(L, 0, -1, 0, 0, 0) == 0;
}

static bool gDone = false;
static uintptr_t gInjectedState = 0;
static int gTries = 0;
static dispatch_source_t gWatcher = nil;
static bool gLuaEnabled = false;
static bool gLuaStarted = false;

static void LuaAttempt();

static void LuaScheduleRetry() {
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(1 * NSEC_PER_SEC)),
                   dispatch_get_main_queue(), ^{ LuaAttempt(); });
}

static uintptr_t LuaCurrentWorld() {
    uintptr_t base = LuaModuleBase();
    if (!base) return 0;
    LuaAppEntry *app = &gApps[LuaAppIndex()];
    uintptr_t getter = base + LuaHex(app->uWorld);
    if (!LuaInText(getter)) return 0;
    long out = 0;
    long ret = ((long (*)(long *))getter)(&out);
    if (LuaValidAddr((uintptr_t)ret)) return (uintptr_t)ret;
    return (uintptr_t)out;
}

static void LuaAttempt() {
    if (!gLuaEnabled) return;
    if (gDone) return;
    if (gTries++ > 600) return;

    uintptr_t base = LuaModuleBase();
    if (!base) { LuaScheduleRetry(); return; }

    LuaAppEntry *app = &gApps[LuaAppIndex()];

    luaL_loadbuffer_t loadbuf =
        (luaL_loadbuffer_t)LuaResolve("luaL_loadbuffer", app->luaL_loadbuffer, base);
    if (!loadbuf)
        loadbuf = (luaL_loadbuffer_t)LuaResolve("luaL_loadbufferx", app->luaL_loadbuffer, base);
    lua_pcall_t pcall = (lua_pcall_t)LuaResolve("lua_pcall", app->lua_pcall, base);

    uintptr_t world = LuaCurrentWorld();
    if (!LuaValidAddr(world)) { LuaScheduleRetry(); return; }

    uintptr_t gi = LuaReadT<uintptr_t>(world + CFG_WORLD_TO_GI);
    if (!LuaValidAddr(gi)) { LuaScheduleRetry(); return; }

    std::vector<uintptr_t> states;
    LuaCollectStates(LuaReadT<uintptr_t>(gi + CFG_GI_TO_WRAPPER), states);

    if (!loadbuf || !pcall || states.empty()) { LuaScheduleRetry(); return; }

    for (uintptr_t L : states) {
        if (!LuaRunChunk((void *)L, loadbuf, pcall, kProbe)) continue;
        if (LuaRunChunk((void *)L, loadbuf, pcall, kSkinsLua)) {
            gInjectedState = L;
            gDone = true;
            NSLog(@"[Lua] injected into state %p", (void *)L);
            return;
        }
        NSLog(@"[Lua] probe ok but payload failed");
    }
    LuaScheduleRetry();
}

static void LuaWatchState() {
    if (!gLuaEnabled) return;
    if (!gDone || !gInjectedState) return;
    uintptr_t world = LuaCurrentWorld();
    if (!LuaValidAddr(world)) return;
    uintptr_t gi = LuaReadT<uintptr_t>(world + CFG_WORLD_TO_GI);
    if (!LuaValidAddr(gi)) return;
    uintptr_t wrapper = LuaReadT<uintptr_t>(gi + CFG_GI_TO_WRAPPER);
    uintptr_t L = LuaReadT<uintptr_t>(wrapper + CFG_WRAPPER_TO_STATE);
    if (LuaValidAddr(L) && L != gInjectedState) {
        gDone = false;
        gInjectedState = 0;
        gTries = 0;
        LuaAttempt();
    }
}

extern "C" bool LuaIsSupported(void) {
    int idx = LuaAppIndex();
    if (idx < 0 || idx >= APP_COUNT) return false;
    LuaAppEntry *app = &gApps[idx];
    if (!app->uWorld || strcmp(app->uWorld, "0") == 0) return false;
    if (!app->luaL_loadbuffer || strcmp(app->luaL_loadbuffer, "0") == 0) return false;
    if (!app->lua_pcall || strcmp(app->lua_pcall, "0") == 0) return false;
    return true;
}

extern "C" void LuaSetEnabled(bool enabled) {
    if (!LuaIsSupported()) return;
    if (enabled == gLuaEnabled) return;
    gLuaEnabled = enabled;
    if (!enabled) return;

    if (!gLuaStarted) {
        gLuaStarted = true;
        gWatcher = dispatch_source_create(DISPATCH_SOURCE_TYPE_TIMER, 0, 0,
                                          dispatch_get_main_queue());
        dispatch_source_set_timer(gWatcher, dispatch_time(DISPATCH_TIME_NOW, 0),
                                  (uint64_t)(3 * NSEC_PER_SEC), (uint64_t)(1 * NSEC_PER_SEC));
        dispatch_source_set_event_handler(gWatcher, ^{ LuaWatchState(); });
        dispatch_resume(gWatcher);
    }
    if (!gDone) {
        dispatch_after(dispatch_time(DISPATCH_TIME_NOW, (int64_t)(5 * NSEC_PER_SEC)),
                       dispatch_get_main_queue(), ^{
            if (!gLuaEnabled) return;
            LuaAttempt();
        });
    }
}

